    if (!session?.current_track_uri) {
      setTrack(null)
      return
    }
    void getTrack(session.current_track_uri)
      .then(setTrack)
      .catch((e: unknown) => {
        setError(e instanceof Error ? e.message : String(e))
      })
  }, [session?.current_track_uri])

  // Realtime subscription — refresh session when DB row updates
  useEffect(() => {
    if (!session) return
    const channel = supabase
      .channel(`weave-session-${session.id}`)
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'weave_sessions',
          filter: `id=eq.${session.id}`,
        },
        (payload) => {
          if (isInactiveRealtimeRow(payload.new)) {
            void navigate('/weave')
            return
          }

          const nextSession = sessionFromRealtimeRow(payload.new)
          if (nextSession) {
            setSession(nextSession)
            applyPlaybackResponse(playbackFromRealtimeRow(payload.new))
            if (queueOpen) {
              void getQueue(nextSession.id).then(setQueue).catch((e: unknown) => {
                setError(e instanceof Error ? e.message : String(e))
              })
            }
          }
        },
      )
      .subscribe((status) => {
        if (status === REALTIME_SUBSCRIBE_STATES.SUBSCRIBED) {
          void getActiveSession().then((s) => {
            if (!s) {
              void navigate('/weave')
              return
            }
            setSession(s)
            void getPlayback(s.id).then(applyPlaybackResponse).catch(() => undefined)
            if (queueOpen) {
              void getQueue(s.id).then(setQueue).catch((e: unknown) => {
                setError(e instanceof Error ? e.message : String(e))
              })
            }
          }).catch((e: unknown) => {
            setError(e instanceof Error ? e.message : String(e))
          })
        }
      })
    return () => { void supabase.removeChannel(channel) }
  }, [navigate, queueOpen, session?.id])

  function handleSkipSong() {
    if (!session) return
    const optimistic = optimisticSkipSong(session, queue)
    wakeHeartbeatUi()
    setPlaybackError(null)
    setPlayerPromptOpen(false)
    if (optimistic) {
      optimisticTrackRef.current = {
        uri: optimistic.item.uri,
        until: Date.now() + 12_000,
      }
      setSession(optimistic.session)
      setTrack(trackDetailsFromQueueItem(optimistic.item))
      setPlayback(playbackFromQueueItem(optimistic.item))
    }
    void skipSong(session.id)
      .then((s) => {
        setSession(s)
        if (queueOpen) {
          void getQueue(s.id).then(setQueue).catch((e: unknown) => {
            setError(e instanceof Error ? e.message : String(e))
          })
        }
        return getPlayback(s.id)
      })
      .then((p) => {
        setPlaybackError(null)
        setPlayerPromptOpen(false)
        applyPlaybackResponse(p)
      })
      .catch((e: unknown) => {
        const message = errorMessage(e)
        if (isSpotifyPlayerActivationError(message)) {
          setPlayerPromptOpen(true)
        } else {
          setPlaybackError(message)
        }
        void getActiveSession().then((s) => {
          setSession(s)
          if (s?.id) {
            void getPlayback(s.id)
              .then(applyPlaybackResponse)
              .catch(() => undefined)
          }
        }).catch(() => undefined)
      })
  }

