async fn build_queue_response(
    state: &AppState,
    session_id: Uuid,
    actor: &PartyActor,
) -> Result<QueueResponse, (StatusCode, Json<Value>)> {
    let session = get_existing_session(state, session_id).await?;
    let items = if session.mode == db::party::PartyMode::BalancedQueue.as_str() {
        let current_owner_key = db::party::current_track_owner_key(
            &state.pool,
            session_id,
            session.current_track_uri.as_deref(),
        )
        .await
        .map_err(|e| err(StatusCode::INTERNAL_SERVER_ERROR, e))?;
        db::party::balanced_queue_items_after(&state.pool, session_id, current_owner_key.as_deref())
            .await
    } else {
        db::party::queue_items(&state.pool, session_id).await
    }
    .map_err(|e| err(StatusCode::INTERNAL_SERVER_ERROR, e))?;

    let raw_votes = db::party::votes_for_queue_items(&state.pool, session_id)
        .await
        .map_err(|e| err(StatusCode::INTERNAL_SERVER_ERROR, e))?;

    let mut vote_map: HashMap<Uuid, Vec<VoterResponse>> = HashMap::new();
    for vote in raw_votes {
        vote_map
            .entry(vote.queue_item_id)
            .or_default()
            .push(VoterResponse {
                user_id: vote
                    .user_id
                    .or(vote.guest_id)
                    .map(|id| id.to_string())
                    .unwrap_or_default(),
                display_name: vote.display_name,
            });
    }

    let items = items
        .into_iter()
        .enumerate()
        .map(|(position, item)| {
            let voters = vote_map.get(&item.id).cloned().unwrap_or_default();
            let vote_count = voters.len() as i64;
            let actor_id = actor.voter_id();
            let user_voted = voters.iter().any(|v| v.user_id == actor_id);
            QueueItemResponse {
                id: item.id,
                uri: item.track.uri.clone(),
                name: item.track.name.clone(),
                artist: item.track.artist.clone(),
                album_art_url: item.track.album_art_url.clone(),
                duration_ms: item.track.duration_ms,
                position,
                pin_position: item.pin_position,
                vote_count,
                user_voted,
                voters,
                added_by_user_id: item.added_by_user_id,
                added_by_guest_id: item.added_by_guest_id,
                from_source_queue: item.from_source_queue,
                queue_owner_key: queue_owner_key(&item),
                queue_owner_name: queue_owner_name(&item),
                added_by_display_name: item.added_by_display_name,
            }
        })
        .collect();

    Ok(QueueResponse { items })
}

fn queue_owner_key(item: &db::party::PartyQueueItem) -> String {
    if item.from_source_queue {
        return "source".to_string();
    }

    queue_owner_key_parts(item.added_by_user_id, item.added_by_guest_id)
        .unwrap_or_else(|| "unknown".to_string())
}

fn queue_owner_key_parts(
    added_by_user_id: Option<Uuid>,
    added_by_guest_id: Option<Uuid>,
) -> Option<String> {
    if let Some(id) = added_by_user_id {
        Some(format!("user:{id}"))
    } else {
        added_by_guest_id.map(|id| format!("guest:{id}"))
    }
}

fn queue_owner_name(item: &db::party::PartyQueueItem) -> String {
    if item.from_source_queue {
        return "Source".to_string();
    }

    item.added_by_display_name
        .clone()
        .unwrap_or_else(|| "Unknown".to_string())
}

